Ниже готовый кеш обложек: три файла целиком и объяснение основных решений. Код я не собирал и не запускал, потому что для этого нужен Mac с Xcode, а его здесь нет. Код вычитала отдельная независимая проверка. Она подтвердила, что двух одновременных загрузок одной обложки не бывает, и нашла несколько проблем, которые я исправил (о них ниже).

### Файл 1: `CoverCache.swift`

```swift
import UIKit

/// Book identifier. Assumed to be UUID; change here if the book model uses another type.
typealias BookID = UUID

/// In-memory cover cache shared by all screens.
///
/// Guarantee: at most one disk load per book id at a time. Concurrent requests for the same id
/// wait for the same load. A failed load is not remembered: the next request retries.
/// After NSCache evicts a cover (memory limit, memory warning, background), it is loaded again.
///
/// Main-actor isolated on purpose: the "cached? already loading?" check and the registration
/// of a new load happen in one synchronous step with no `await` in between, so two callers
/// can never both start a load for the same id. Disk work itself runs off the main actor.
@MainActor
final class CoverCache {
    typealias Loader = @Sendable (BookID) async throws -> UIImage

    static let shared = CoverCache()

    private let memory = NSCache<NSUUID, UIImage>()
    private var inFlight: [BookID: Task<UIImage, any Error>] = [:]
    private let loader: Loader

    init(loader: @escaping Loader = { try await loadCoverFromDisk(id: $0) }) {
        self.loader = loader
        memory.totalCostLimit = 80 * 1024 * 1024
    }

    /// Returns the cover only if it is already in memory, so a view can show it on the first frame.
    func cachedCover(for id: BookID) -> UIImage? {
        memory.object(forKey: id as NSUUID)
    }

    /// Returns the cover, joining an in-flight load for the same id if there is one.
    /// Cancelling one caller does not cancel the shared load: other screens may still need it.
    func cover(for id: BookID) async throws -> UIImage {
        if let image = cachedCover(for: id) { return image }
        let task = inFlight[id] ?? startLoad(for: id)
        let image = try await task.value
        try Task.checkCancellation()
        return image
    }

    private func startLoad(for id: BookID) -> Task<UIImage, any Error> {
        let loader = self.loader
        // A plain Task inherits main-actor isolation and is enqueued, so its body starts only
        // after `inFlight[id] = task` below. The memory write and the removal from inFlight
        // happen in one synchronous step, so there is no moment when a cover is in neither.
        let task = Task {
            defer { self.inFlight[id] = nil }
            let image = try await Self.loadOffMain(id, using: loader)
            self.memory.setObject(image, forKey: id as NSUUID, cost: Self.cost(of: image))
            return image
        }
        inFlight[id] = task
        return task
    }

    /// Runs the loader and the image decode on the background pool, not on the main thread.
    @concurrent
    private nonisolated static func loadOffMain(_ id: BookID, using loader: Loader) async throws -> UIImage {
        let image = try await loader(id)
        return await image.byPreparingForDisplay() ?? image
    }

    private static func cost(of image: UIImage) -> Int {
        guard let cgImage = image.cgImage else { return 1 }
        return cgImage.bytesPerRow * cgImage.height
    }
}
```

### Файл 2: `BookCoverView.swift` (как экраны пользуются кешем)

```swift
import SwiftUI

struct BookCoverView: View {
    let bookID: BookID
    @State private var image: UIImage?

    var body: some View {
        ZStack {
            Color.secondary.opacity(0.15)
            if let image {
                Image(uiImage: image).resizable().scaledToFill()
            }
        }
        .aspectRatio(2.0 / 3.0, contentMode: .fit)
        .clipped()
        .task(id: bookID) {
            image = CoverCache.shared.cachedCover(for: bookID)
            guard image == nil else { return }
            let loaded = try? await CoverCache.shared.cover(for: bookID)
            // The view may have switched to another book while this load was running.
            guard !Task.isCancelled else { return }
            image = loaded
        }
    }
}
```

### Файл 3: `CoverCacheTests.swift` (в тестовую часть проекта, не в само приложение)

```swift
import Testing
import UIKit
@testable import Slumpy

private actor LoadCounter {
    private(set) var value = 0
    func increment() { value += 1 }
}

private struct LoadFailure: Error {}

private actor FailsOnceLoader {
    private(set) var calls = 0
    func load() throws -> UIImage {
        calls += 1
        if calls == 1 { throw LoadFailure() }
        return UIImage()
    }
}

@MainActor
struct CoverCacheTests {
    @Test func concurrentRequestsLoadFromDiskOnce() async throws {
        let counter = LoadCounter()
        let cache = CoverCache { _ in
            await counter.increment()
            try await Task.sleep(for: .milliseconds(100))
            return UIImage()
        }
        let id = BookID()
        async let first = cache.cover(for: id)
        async let second = cache.cover(for: id)
        _ = try await (first, second)
        _ = try await cache.cover(for: id)
        #expect(await counter.value == 1)
    }

    @Test func failedLoadIsRetriedOnNextRequest() async throws {
        let loader = FailsOnceLoader()
        let cache = CoverCache { _ in try await loader.load() }
        let id = BookID()
        await #expect(throws: LoadFailure.self) { try await cache.cover(for: id) }
        _ = try await cache.cover(for: id)
        #expect(await loader.calls == 2)
    }
}
```

### Основные решения

- **Почему двойная загрузка невозможна.** Кеш держит список обложек, которые загружаются прямо сейчас. Если второй экран просит обложку, которая уже грузится, он не запускает новую загрузку, а ждёт ту, что идёт. Проверка «есть ли обложка в памяти или в загрузке» и запись новой загрузки в этот список происходят одним шагом, без пауз. Поэтому два экрана не могут проскочить между ними. Первый тест проверяет именно это.
- **Чтение с диска не тормозит интерфейс.** Загрузка и подготовка картинки к показу идут в фоне, поэтому списки не дёргаются при прокрутке.
- **Обложка из памяти показывается сразу**, без мигания заглушки.
- **Ошибка не запоминается.** Если обложка не загрузилась, следующий запрос попробует снова. Это проверяет второй тест.
- **Если экран закрыли, загрузка не прерывается**, потому что эта же обложка может быть нужна другому экрану. При быстрой смене книги в одной карточке не появится обложка от предыдущей книги: эту ошибку нашла проверка, и я её исправил.

### Допущения

1. **«Не грузить дважды» я понял как «не грузить дважды одновременно».** Под память отведено около 80 МБ, это примерно 30–40 обложек обычного размера. Если память кончится, телефону её не хватает или приложение ушло в фон, старые обложки удаляются из памяти и потом снова читаются с диска. Иначе на большой библиотеке приложение могло бы занять всю память. Пользователь заметит это разве что как короткую заглушку при возврате к давно открытой обложке.
2. **Идентификатор книги — UUID**, а модуль приложения называется `Slumpy`. Если это не так, нужно поменять одну строку в первом файле и одну в тестах.
3. **Обложки на диске уменьшенные, а не исходные картинки огромного размера.** Если хранятся оригиналы, их стоит уменьшать при сохранении. Это отдельная задача.
4. **Что сделать с `loadCoverFromDisk`.** Если эта функция лежит в коде приложения без специальных пометок, Swift выполняет её на главном потоке, и тогда чтение с диска всё равно будет тормозить интерфейс. Чтобы это исправить, в её объявлении перед `func` нужно добавить `@concurrent nonisolated`. Без этой правки кеш работает правильно, просто медленнее для интерфейса.
5. **Известное ограничение.** Если очень быстро пролистать длинную библиотеку, начатые загрузки обложек, которые уже уехали с экрана, всё равно доделываются. Видимые обложки могут появиться чуть позже. Отменять такие загрузки я сознательно не стал: это заметно усложняет код, а выигрыш небольшой. Если на телефоне это станет заметно, это отдельная доработка.

**Что проверить на iPhone:** открыть библиотеку и быстро пролистать её вверх и вниз. Обложки не должны мигать или подменять друг друга, прокрутка должна идти плавно. Ещё стоит открыть одну книгу сразу из двух мест, например из списка и из профиля друга: обложка должна быть одинаковой в обоих местах.

